from itertools import combinations, permutations
from pysat.solvers import Glucose3

n = 20
colors = 3
num_edge_vars = n*(n-1)//2

def edge_var(u, v):
    if u > v: u, v = v, u
    idx = u * n - u*(u+1)//2 + (v - u - 1)
    return idx + 1

def color_var(v, k):
    return num_edge_vars + v * colors + k + 1

clauses = []

# 1. Each vertex has exactly one color
for v in range(n):
    clauses.append([color_var(v, k) for k in range(colors)])
    for k1 in range(colors):
        for k2 in range(k1+1, colors):
            clauses.append([-color_var(v, k1), -color_var(v, k2)])

# 2. Proper coloring: if edge exists, endpoints differ in color
for u, v in combinations(range(n), 2):
    ev = edge_var(u, v)
    for k in range(colors):
        clauses.append([-ev, -color_var(u, k), -color_var(v, k)])

# 3. No C3 (triangle-free)
for u, v, w in combinations(range(n), 3):
    clauses.append([-edge_var(u,v), -edge_var(v,w), -edge_var(u,w)])

# 4. No C4
for a, b, c, d in combinations(range(n), 4):
    for cycle in [(a,b,c,d), (a,b,d,c), (a,c,b,d)]:
        u,v,w,x = cycle
        clauses.append([-edge_var(u,v), -edge_var(v,w), -edge_var(w,x), -edge_var(x,u)])

print(f"After C4: {len(clauses)}")

# 5. No C5
def get_distinct_cycles(verts, length):
    """Get all distinct cycles of given length on given vertices as lists of edges"""
    v = list(verts)
    cycles = set()
    for perm in permutations(v[1:]):
        cycle = (v[0],) + perm
        edges = tuple(sorted([tuple(sorted([cycle[i], cycle[(i+1)%length]])) for i in range(length)]))
        cycles.add(edges)
    return cycles

for combo in combinations(range(n), 5):
    for cycle_edges in get_distinct_cycles(combo, 5):
        clause = [-edge_var(u, v) for u, v in cycle_edges]
        clauses.append(clause)

print(f"After C5: {len(clauses)}")

# 6. No C6
for combo in combinations(range(n), 6):
    for cycle_edges in get_distinct_cycles(combo, 6):
        clause = [-edge_var(u, v) for u, v in cycle_edges]
        clauses.append(clause)

print(f"After C6: {len(clauses)}")
